    N = lambda x: sum(1 for k, _ in G if k == x)
    M = max(l for _, l in G)
    C = sorted((w.count(x), x) for x in COL)
    e = w[0] if q[0] == "0" else w[-1]
    RL = [l for _, l in G]
    return [w[1] == w[-2],                                              # 0  2nd == 2nd-from-last
            {k for k, l in G if l == M} == {e},                         # 1  biggest clump's colour
            N(e) == 1,                                                  # 2  that colour, one clump
            C[0][0] < C[1][0] and C[0][1] == e,                         # 3  that colour is rarest
            q[0] in w and all(w[i:i + 2] == q for i in range(len(w)) if w[i] == q[0]),   # 4
            q[0] in w and q[1] in w and N(q[0]) == N(q[1]),             # 5  as many clumps
            q[0] in w and q[1] in w and w.rfind(q[0]) < w.find(q[1]),   # 6  all X before all Y
