def MASKOF(w):
    """Which rules of U does w obey?  One pass, same answers as P (verified over all 88 209
    strings of length 6-10); it is only here to keep the module-level table cheap."""
    G = [(k, len(list(g))) for k, g in itertools.groupby(w)]
