def near(x, y):
    """x is y, or one bead changed / added / removed.  Keeps the EXAMPLES apart only."""
    if len(x) == len(y):
        return sum(p != q for p, q in zip(x, y)) < 2
    if len(x) > len(y):
        x, y = y, x
    return len(y) - len(x) == 1 and any(y[:i] + y[i + 1:] == x for i in range(len(y)))


