def XFEAT(w):
    """(longest clump, #R, #G, #B, colour set, which colours are doubled, first bead,
        last bead, number of clumps, all clumps the same size, palindrome,
        shortest clump, each colour in one clump)"""
    G = [len(list(g)) for _, g in itertools.groupby(w)]
    cs = 0
    db = 0
    for i, c in enumerate(COL):
        if c in w:
            cs |= 1 << i
        if c + c in w:
            db |= 1 << i
    return (max(G), w.count("R"), w.count("G"), w.count("B"), cs, db, w[0], w[-1],
            len(G), int(len(set(G)) == 1), int(w == w[::-1]), min(G),
            int(len(G) == len(set(w))))


def TRAPS(X):
    """The excluded rules -- never in U -- that are consistent with EVERY example
