        elif h == 5:
            b = x[c[1]] > x[c[2]]
        elif h == 6:
            b = x[6] == c[1]
        elif h == 7:
            b = x[7] == c[1]
        elif h == 8:
            b = x[6] == x[7]
        elif h == 9:
            b = x[0] == 1
        elif h == 10:
            b = x[8] == c[1]
        elif h == 11:
            b = x[9] == 1
        elif h == 12:
            b = x[10] == 1
        elif h == 13:
