        mm = [comp(i) for i in pick]
        sc = []
        for a in range(K):
            u = mm[a]
            for b2 in range(K):
                if a != b2:
                    u &= ~mm[b2]
            x = -1.0
            while u:
                l = u & -u
                k = l.bit_length() - 1
                if S[k] > x:
                    x = S[k]
                u ^= l
            sc.append(x)
        ov = [sum(look(pick[a], pick[b2]) for b2 in range(K) if b2 != a) for a in range(K)]
        d = 3 * abs(sum(1 for a in range(1, K) if sc[a] > sc[0]) - a1) \
            + 2 * abs(sum(1 for a in range(1, K) if mm[a].bit_count() > mm[0].bit_count()) - a2) \
            + abs(sum(1 for a in range(1, K) if ov[a] > ov[0]) - a3)
        if d < bd:
            bd = d
            best = pick
            if d == 0:
                break
    out = [POOL[i] for i in best]
    r.shuffle(out)
    return out


def LINEUP(r, j, ex, C, tr, ne):
    """K bead strings of ONE length, exactly one of which obeys the rule.  Every decoy
    breaks the rule, fires EXACTLY the same example-consistent excluded rules as the true
    candidate (revision 2 sec.5b) and uses the same number of colours; RANKS then aims the
    truth's place in the rarity order."""
    b = 1 << j
    d = SATL[j]
    ES = set(ex)
    LS = [L for L in d if len(d[L]) > 2 and len(BYLEN.get(L, ())) > 200]
    r.shuffle(LS)
