            if best is None:
                break
            C = -1
            for i in best:
                C &= BM[i]
            tr = TRAPS([XF[i] for i in best])
            line = LINEUP(r, j, best, C, tr, len(best) - 2)
            if line is not None:
                return "\n".join(POOL[i] for i in best) + "\n\n" + "\n".join(line)
    # never reached in 20 000 seeds, but kept scoreable all the same: the seed-0 clue,
    # whose single survivor is "only two colours are used"
    return "GRRGGRRG\nGGRGRR\n\nRRBRRB\nBRGRRB\nBRRGBR\nRRBGRB\nRBGRRB"
